			break
		}
		line = line[:len(line)-1]
		words := split(line)
		for _, word := range words {
			if len(word) >= 2 && len(s) >= 2 && (s[0] == word[0] || s[1] == word[1]) {
				matches = true
				break
			}
		}
		if matches {
			break
		}
	}

	if matches {
		fmt.Fprintln(writer, "YES")
	} else {
		fmt.Fprintln(writer, "NO")
	}
}

func split(s string) []string {
	var result []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' {
			if i > start {
				result = append(result, s[start:i])
			}
			start = i + 1
		}
	}
	if start < len(s) {
		result = append(result, s[start:])
	}
	return result
}
